package main

import (
	"io"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func Test_run_RemovesStaleGeneratedFiles(t *testing.T) {
	t.Parallel()

	out := t.TempDir()
	dir := filepath.Join(out, "sts")
	require.NoError(t, os.MkdirAll(dir, dirPerm))

	files := map[string]string{
		"codec_old.go":   generatedHeader + "package sts\n",                 // generated by an earlier run
		"types.go":       generatedHeader + "package sts\n\ntype Old int\n", // generated, and still produced
		"sts_test.go":    "package sts\n",                                   // hand-written
		"short.go":       "package sts\n",                                   // shorter than the header
		"notes.txt":      generatedHeader,                                   // not Go
		"other_gen.go":   "// Code generated by stringer. DO NOT EDIT.\n\npackage sts\n",
		"handwritten.go": "// Package sts is hand-written.\npackage sts\n",
	}

	for name, content := range files {
		require.NoError(t, os.WriteFile(filepath.Join(dir, name), []byte(content), filePerm))
	}

	err := run([]string{"-specs", "../../../specs", "-out", out, "-services", "sts"}, io.Discard)
	require.NoError(t, err)

	assert.NoFileExists(t, filepath.Join(dir, "codec_old.go"), "a generated file this run did not write")

	for _, kept := range []string{"sts_test.go", "short.go", "notes.txt", "other_gen.go", "handwritten.go"} {
		assert.FileExists(t, filepath.Join(dir, kept))
	}

	types, err := os.ReadFile(filepath.Join(dir, "types.go"))
	require.NoError(t, err)
	assert.NotContains(t, string(types), "type Old int", "rewritten by this run")

	for _, name := range []string{"codec_json.go", "codec_query.go", "dispatch.go", "errors.go", "operations.go"} {
		assert.FileExists(t, filepath.Join(dir, name))
	}
}
